document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("wall-area-form"),t=document.getElementById("wall-area-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("wall-length").value),l=parseFloat(document.getElementById("wall-width").value),a=parseFloat(document.getElementById("wall-height").value),o=parseFloat(document.getElementById("wall-doors").value)||0;if(n<=0||l<=0||a<=0)return t.textContent="Please enter positive values for room dimensions and wall height.",void 0;const s=2*(n+l)*a,r=s-o,i=Math.ceil(r/375),d=Math.ceil(2*r/375),m=Math.ceil(r/325),p=Math.ceil(r/28);t.innerHTML=`\n        <div class="result-section">\n          <h4>Wall Surface Area:</h4>\n          <p><strong>${s.toFixed(1)} sq ft</strong> (total wall area)</p>\n          <p><strong>${r.toFixed(1)} sq ft</strong> (minus doors & windows)</p>\n          <p>Room perimeter: ${(2*(n+l)).toFixed(1)} ft</p>\n        </div>\n        <div class="result-materials">\n          <h4>Material Estimates:</h4>\n          <p><strong>Paint needed:</strong></p>\n          <ul>\n            <li>1 coat: ${i} gallon${i>1?"s":""}</li>\n            <li>2 coats: ${d} gallon${d>1?"s":""}</li>\n          </ul>\n          <p><strong>Primer:</strong> ${m} gallon${m>1?"s":""}</p>\n          <p><strong>Wallpaper:</strong> ~${p} rolls (standard width)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>🎨 Paint coverage: ~375 sq ft per gallon (varies by brand and surface)</em></p>\n          <p><em>📏 Always buy slightly more than calculated for touch-ups</em></p>\n          <p><em>🏠 For textured walls, add 10-20% more paint</em></p>\n        </div>\n      `})});